// Writes the annotation specs for retest round 6 (26 Oct 2026, CRM) and renders them with annotate.js.
// Usage: node cards-r6.js (once, renders API cards + row boxes) → node specs-r6.js [ticket ...] → screenshots/annotated/NDC-<n>-retest-<VERDICT>.png
// Source of truth: notes-r6.md (verdicts + facts), tickets.md (expected), automation FACT/RESULT lines (quoted on the cards).
const fs = require('fs'); const path = require('path'); const { execFileSync } = require('child_process');
const RAW = path.join(__dirname, '..', 'screenshots', 'raw');
const ENV = { env: 'staging-crm.taviportal.com · tenant NDC-Staging · Edge (headless) + API · mahmoud.mahamed1515 (CRM Admin); test users 1/2, automation where noted', date: '26 Oct 2026' };
const DIM = n => { const b = fs.readFileSync(path.join(RAW, n)); return [b.readUInt32BE(16), b.readUInt32BE(20)]; };
const P = (img, caption, crop, boxes) => { const [w, h] = DIM(img); return { img, caption, crop: crop || [0, 0, w, h], w, h, boxes: boxes.map(([b, n, kind]) => ({ b, n, kind })) }; };
// API card as a full-width panel; marks = [[row (1-based), n, kind]] → box on that row's response column
const BOX = JSON.parse(fs.readFileSync(path.join(__dirname, 'cards-r6', 'boxes.json'), 'utf8'));
const CARD = (out, caption, marks) => { const rows = BOX[out]; if (!rows) throw new Error('no card ' + out + ' — run cards-r6.js');
  const p = P(out, caption, [0, 0, 1600, rows[rows.length - 1][3] + 20], marks.map(([r, n, kind]) => [[924, rows[r - 1][1] - 2, 1566, rows[r - 1][3] + 2], n, kind])); p.full = true; return p; };
const ALL = (out, kind = 'PASS') => BOX[out].map((_, i) => [i + 1, i + 1, kind]);

